  h.control.holdMainMasks=true;const b=await h.prepareBatch(r,[component(1)]);h.commit(r,b,2);b.scope.release();await h.settle(r,()=>r.getProgramPreparationStats()[0].resourceResidency.candidateMainProgramCount===1);
