test('root500 packed catalog demand waits under its resident pin, cancels independently and reacquires without changing published paint facts',async()=>{
 const h=fixture({city:'hamburg'});await h.environment(async()=>{
  const r=h.create(),rows=[component(1),component(2)];for(const row of rows)row.city='hamburg';
  const records=values=>values.map(row=>({city:row.city,objectId:row.objectId,partId:row.partId,coloredVertices:count([row])}));
  const firstRecords=records([rows[0]]);h.control.paintedIDs=new Set([key(rows[0])]);h.control.progressiveRows=firstRecords;
  const first=await h.prepareBatch(r,rows);assert.equal(h.programRequests.length,0,'catalog selection follows the actual CPU family runs');
  assert(h.materialRequests[0].rows.some(row=>row===rows[0]));assert(h.materialRequests[0].rows.some(row=>row===rows[1]));
  h.commit(r,first,1);first.scope.release();r.setEnabled(true);r.layer.onAdd({},h.gl);await h.settle(r);
  assert.equal(h.programRequests.length,1);assert.deepEqual(new Set(h.programRequests[0].keys),new Set(['base','family-2','family-1']));
  assert.equal(first.scope.stats.ownerReleased,true);assert.equal(first.scope.stats.pins,1);assert.equal(first.scope.stats.resources,2);
  const published=r.borrowSurfaceComponent(rows[0]),other=r.borrowSurfaceComponent(rows[1]),gpu=[...h.buffers.keys()];
  assert.equal(published.displayEstimates.progressivePainted,true);assert.equal(other.displayEstimates.progressivePainted,false);
  assert.strictEqual(published.sourceFeature,rows[0].sourceFeature);assert.strictEqual(published.batches[0].positions,rows[0].batches[0].positions);
  assert.deepEqual(r.getProgressiveRenderStatus(),firstRecords);
  // Content-addressed chunk reuse (controller ruling 2026-11-03 01:15, same as residency #1): replaying
  // the same prepared scope hits its resident chunks and admits no source, upload or GPU allocation (+0).
  // Mutating the fixture's paint inputs after preparation cannot leak into the replay: the published
  // paint facts are the scope's frozen records.
  const storeBefore={...h.store.stats};h.control.progressiveRows=records([rows[1]]);h.control.paintedIDs=new Set([key(rows[1])]);h.commit(r,first,2);
  await h.settle(r);assert.equal(r.stats.geometryPreparation.candidateFailure,undefined);assert.equal(r.getRevision().generation,2,'the identical same-scope replay publishes by reuse');
  assert(h.store.stats.hits>storeBefore.hits,'the replay hit the resident chunks');assert.equal(h.store.stats.productions,storeBefore.productions,'the replay produced no new chunk resource');assert.equal(h.store.stats.gpuAllocations,storeBefore.gpuAllocations,'the replay allocated no GPU resource');
  // The reuse republishes the same canonical CPU objects under the new generation stamp.
  const republished=r.borrowSurfaceComponent(rows[0]);assert.equal(published.generation,1);{const actual=republished;assert.deepEqual(actual,{...published,generation:2});for(const name of ['sourceFeature','componentGeometry','batches','origin'])assert.strictEqual(actual[name],published[name],name+' retains its canonical reference across the reuse');for(let i=0;i<published.batches.length;i++)for(const name of ['positions','normals','indices','color'])assert.strictEqual(actual.batches[i][name],published.batches[i][name],name+' retains its canonical buffer across the reuse');}assert.equal(published.displayEstimates.progressivePainted,true);assert.equal(other.displayEstimates.progressivePainted,false);assert.equal(r.borrowSurfaceComponent(rows[1]).displayEstimates.progressivePainted,false);
  assert.deepEqual(r.getProgressiveRenderStatus(),firstRecords,'a reused same-scope candidate publishes its frozen paint records, not later mutable inputs');assert.equal(first.scope.stats.disposed,false);assert.equal(first.scope.stats.pins,1);
  assert.deepEqual([...h.buffers.keys()],gpu);assert.equal(h.programRequests.length,1,'the already declared catalog selection is reused');
  const nextRows=[component(3),component(4)];for(const row of nextRows)row.city='hamburg';
  const abort=new AbortController(),candidate=await h.prepareBatch(r,nextRows,abort.signal),gate={};h.control.programGate=gate;h.control.progressiveRows=records([nextRows[0]]);h.control.paintedIDs=new Set([key(nextRows[0])]);
  h.commit(r,candidate,3);candidate.scope.release();await h.settle(r,()=>h.programRequests.length===2);
  const request=h.programRequests.at(-1);assert.deepEqual(new Set(request.keys),new Set(['base','family-2','family-1']));
  assert.equal(candidate.scope.stats.ownerReleased,true);assert.equal(candidate.scope.stats.pins,1);assert.equal(candidate.scope.stats.pending,1);assert.equal(request.signal.aborted,false);
  assert.equal(r.getRevision().generation,2);assertPublishedComponent(r.borrowSurfaceComponent(rows[0]),republished);assert.deepEqual(r.getProgressiveRenderStatus(),firstRecords);assert.deepEqual([...h.buffers.keys()],gpu);
  abort.abort();await h.settle(r,()=>candidate.scope.stats.disposed);assert.equal(request.signal.aborted,true);assert.deepEqual(candidate.scope.stats,{resources:0,pending:0,pins:0,ownerReleased:true,disposed:true});assert.equal(first.scope.stats.disposed,false);assert.deepEqual([...h.buffers.keys()],gpu);
  gate.release();await Promise.resolve();await Promise.resolve();h.frame(r);assert.equal(r.getRevision().generation,2);assertPublishedComponent(r.borrowSurfaceComponent(rows[0]),republished);
  h.control.programGate=undefined;const replacement=await h.prepareBatch(r,nextRows);h.commit(r,replacement,3);replacement.scope.release();await h.settle(r);
  assert.equal(h.programRequests.length,3);assert.equal(r.getRevision().generation,3);assert.equal(first.scope.stats.disposed,true);assert.equal(r.getComponent(nextRows[0]).displayEstimates.progressivePainted,true);assert.deepEqual(r.getProgressiveRenderStatus(),records([nextRows[0]]));
  r.destroy();assertReleasedSourcePlans(h);assert.equal(replacement.scope.stats.disposed,true);assert.equal(h.buffers.size,0);assert(h.ledgers.every(ledger=>ledger.released===1));
 });
});

